def flujo_de_aprobacion(apps, schema_editor):
    """Las funcionalidades existentes quedan aprobadas tal como están (sin cambios en sus valores)
    y se suman al flujo de aprobación de los demás contenidos."""
    ContentType = apps.get_model("contenttypes", "ContentType")
    Workflow = apps.get_model("wagtailcore", "Workflow")
    WorkflowContentType = apps.get_model("wagtailcore", "WorkflowContentType")
    wf = Workflow.objects.filter(active=True).first()
    if wf:
        ct, _ = ContentType.objects.get_or_create(app_label="contenidos", model="funcionalidad")
        WorkflowContentType.objects.get_or_create(content_type=ct, defaults={"workflow": wf})


